<?php session_start();header('Content-Type: application/json');require 'config.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;} $u=trim($_POST['usuario']??'');$p=$_POST['password']??'';$s=$pdo->prepare('SELECT id,usuario,password_hash FROM administradores WHERE usuario=:u LIMIT 1');$s->execute([':u'=>$u]);$a=$s->fetch();if(!$a||!password_verify($p,$a['password_hash'])){http_response_code(401);echo json_encode(['message'=>'Usuario o contraseña incorrectos.']);exit;}session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_usuario']=$a['usuario'];echo json_encode(['ok'=>true]);
